import{_ as l,a0 as a,w as c,s as n,ao as p,I as d,x as s,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"more、less 和 most 的區別 | LCTT x X-CMD","titleTemplate":false,"description":"more、less 和 most 的區別 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"more、less 和 most 的區別 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"more、less 和 most 的區別 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181108 The Difference Between more, less And most Commands","title":"more、less 和 most 的區別","tag":"201811","desc":""},"relativePath":"201811/20181108 The Difference Between more, less And most Commands.md","filePath":"[post].md"}'),r={name:"201811/20181108 The Difference Between more, less And most Commands.md"};function h(g,e,m,k,u,b){const o=a("Link");return c(),n("div",null,[e[15]||(e[15]=p('<h1 id="more、less-和-most-的區別" tabindex="-1">more、less 和 most 的區別 <a class="header-anchor" href="#more、less-和-most-的區別" aria-label="Permalink to “more、less 和 most 的區別”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/11/more-less-and-most-commands-720x340.png" alt=""></p><p>如果你是一個 Linux 方面的新手，你可能會在 <code>more</code>、<code>less</code>、<code>most</code> 這三個命令列工具之間產生疑惑。在本文當中，我會對這三個命令列工具進行對比，以及展示它們各自在 Linux 中的一些使用例子。總的來説，這幾個命令列工具之間都有相通和差異，而且它們在大部分 Linux 發行版上都有自帶。</p><p>我們首先來看看 <code>more</code> 命令。</p><h3 id="more-命令" tabindex="-1">more 命令 <a class="header-anchor" href="#more-命令" aria-label="Permalink to “more 命令”">​</a></h3><p><code>more</code> 是一個老式的、基礎的終端分頁閲讀器，它可以用於打開指定的文件並進行交互式閲讀。如果文件的內容太長，在一屏以內無法完整顯示，就會逐頁顯示文件內容。使用回車鍵或者空格鍵可以滾動瀏覽文件的內容，但有一個限制，就是隻能夠單向滾動。也就是説只能按順序往下翻頁，而不能進行回看。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/11/more-command-demo.gif" alt=""></p><p><strong>更正</strong></p><p>有的 Linux 用户向我指出，在 <code>more</code> 當中是可以向上翻頁的。不過，最原始版本的 <code>more</code> 確實只允許向下翻頁，在後續出現的較新的版本中也允許了有限次數的向上翻頁，只需要在瀏覽過程中按 <code>b</code> 鍵即可向上翻頁。唯一的限制是 <code>more</code> 不能搭配管道使用（如 <code>ls | more</code>）。（LCTT 譯註：此處原作者疑似有誤，譯者使用 <code>more</code> 是可以搭配管道使用的，或許與不同 <code>more</code> 版本有關）</p><p>按 <code>q</code> 即可退出 <code>more</code>。</p><p><strong>更多示例</strong></p><p>打開 <code>ostechnix.txt</code> 文件進行交互式閲讀，可以執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ more ostechnix.txt</span></span></code></pre></div><p>在閲讀過程中，如果需要查找某個字符串，只需要像下面這樣輸入斜槓（<code>/</code>）之後接着輸入需要查找的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/linux</span></span></code></pre></div><p>按 <code>n</code> 鍵可以跳轉到下一個匹配的字符串。</p><p>如果需要在文件的第 <code>10</code> 行開始閲讀，只需要執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ more +10 file</span></span></code></pre></div><p>就可以從文件的第 <code>10</code> 行開始顯示文件的內容了。</p><p>如果你需要讓 <code>more</code> 提示你按空格鍵來翻頁，可以加上 <code>-d</code> 參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ more -d ostechnix.txt</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/11/more-1.png" alt=""></p><p>如上圖所示，<code>more</code> 會提示你可以按空格鍵翻頁。</p><p>如果需要查看所有選項以及對應的按鍵，可以按 <code>h</code> 鍵。</p><p>要查看 <code>more</code> 的更多詳細信息，可以參考手冊：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man more</span></span></code></pre></div><h3 id="less-命令" tabindex="-1">less 命令 <a class="header-anchor" href="#less-命令" aria-label="Permalink to “less 命令”">​</a></h3><p><code>less</code> 命令也是用於打開指定的文件並進行交互式閲讀，它也支持翻頁和搜索。如果文件的內容太長，也會對輸出進行分頁，因此也可以翻頁閲讀。比 <code>more</code> 命令更好的一點是，<code>less</code> 支持向上翻頁和向下翻頁，也就是可以在整個文件中任意閲讀。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/11/less-command-demo.gif" alt=""></p><p>在使用功能方面，<code>less</code> 比 <code>more</code> 命令具有更多優點，以下列出其中幾個：</p><ul><li>支持向上翻頁和向下翻頁</li><li>支持向上搜索和向下搜索</li><li>可以跳轉到文件的末尾並立即從文件的開頭開始閲讀</li><li>在編輯器中打開指定的文件</li></ul><p><strong>更多示例</strong></p><p>打開文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ less ostechnix.txt</span></span></code></pre></div><p>按空格鍵或回車鍵可以向下翻頁，按 <code>b</code> 鍵可以向上翻頁。</p><p>如果需要向下搜索，在輸入斜槓（<code>/</code>）之後接着輸入需要搜索的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/linux</span></span></code></pre></div><p>按 <code>n</code> 鍵可以跳轉到下一個匹配的字符串，如果需要跳轉到上一個匹配的字符串，可以按 <code>N</code> 鍵。</p><p>如果需要向上搜索，在輸入問號（<code>?</code>）之後接着輸入需要搜索的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?linux</span></span></code></pre></div><p>同樣是按 <code>n</code> 鍵或 <code>N</code> 鍵跳轉到下一個或上一個匹配的字符串。</p><p>只需要按 <code>v</code> 鍵，就會將正在閲讀的文件在默認編輯器中打開，然後就可以對文件進行各種編輯操作了。</p><p>按 <code>h</code> 鍵可以查看 <code>less</code> 工具的選項和對應的按鍵。</p><p>按 <code>q</code> 鍵可以退出閲讀。</p><p>要查看 <code>less</code> 的更多詳細信息，可以參考手冊：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man less</span></span></code></pre></div><h3 id="most-命令" tabindex="-1">most 命令 <a class="header-anchor" href="#most-命令" aria-label="Permalink to “most 命令”">​</a></h3><p><code>most</code> 同樣是一個終端閲讀工具，而且比 <code>more</code> 和 <code>less</code> 的功能更為豐富。<code>most</code> 支持同時打開多個文件。你可以在打開的文件之間切換、編輯當前打開的文件、迅速跳轉到文件中的某一行、分屏閲讀、同時鎖定或滾動多個屏幕等等功能。在默認情況下，對於較長的行，<code>most</code> 不會將其截斷成多行顯示，而是提供了左右滾動功能以在同一行內顯示。</p><p><strong>更多示例</strong></p><p>打開文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ most ostechnix1.txt</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/11/most-command.png" alt=""></p><p>按 <code>e</code> 鍵可以編輯當前文件。</p><p>如果需要向下搜索，在斜槓（<code>/</code>）或 <code>S</code> 或 <code>f</code> 之後輸入需要搜索的內容，按 <code>n</code> 鍵就可以跳轉到下一個匹配的字符串。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/11/most-1-1.gif" alt=""></p><p>如果需要向上搜索，在問號（<code>?</code>）之後輸入需要搜索的內容，也是通過按 <code>n</code> 鍵跳轉到下一個匹配的字符串。</p><p>同時打開多個文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ most ostechnix1.txt ostechnix2.txt ostechnix3.txt</span></span></code></pre></div><p>在打開了多個文件的狀態下，可以輸入 <code>:n</code> 切換到下一個文件，使用 <code>↑</code> 或 <code>↓</code> 鍵選擇需要切換到的文件，按回車鍵就可以查看對應的文件。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/11/most-2.gif" alt=""></p><p>要打開文件並跳轉到某個字符串首次出現的位置（例如 linux），可以執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ most file +/linux</span></span></code></pre></div><p>按 <code>h</code> 鍵可以查看幫助。</p><p><strong>按鍵操作列表</strong></p><p>移動：</p><ul><li>空格鍵或 <code>D</code> 鍵 – 向下滾動一屏</li><li><code>DELETE</code> 鍵或 <code>U</code> 鍵 – 向上滾動一屏</li><li><code>↓</code> 鍵 – 向下移動一行</li><li><code>↑</code> 鍵 – 向上移動一行</li><li><code>T</code> 鍵 – 移動到文件開頭</li><li><code>B</code> 鍵 – 移動到文件末尾</li><li><code>&gt;</code> 鍵或 <code>TAB</code> 鍵 – 向右滾動屏幕</li><li><code>&lt;</code> 鍵 – 向左滾動屏幕</li><li><code>→</code> 鍵 – 向右移動一列</li><li><code>←</code> 鍵 – 向左移動一列</li><li><code>J</code> 鍵或 <code>G</code> 鍵 – 移動到某一行，例如 <code>10j</code> 可以移動到第 10 行</li><li><code>%</code> 鍵 – 移動到文件長度某個百分比的位置</li></ul><p>窗口命令：</p><ul><li><code>Ctrl-X 2</code>、<code>Ctrl-W 2</code> – 分屏</li><li><code>Ctrl-X 1</code>、<code>Ctrl-W 1</code> – 只顯示一個窗口</li><li><code>O</code> 鍵、<code>Ctrl-X O</code> – 切換到另一個窗口</li><li><code>Ctrl-X 0</code> – 刪除窗口</li></ul><p>文件內搜索：</p><ul><li><code>S</code> 鍵或 <code>f</code> 鍵或 <code>/</code> 鍵 – 向下搜索</li><li><code>?</code> 鍵 – 向上搜索</li><li><code>n</code> 鍵 – 跳轉到下一個匹配的字符串</li></ul><p>退出：</p><ul><li><code>q</code> 鍵 – 退出 <code>most</code> ，且所有打開的文件都會被關閉</li><li><code>:N</code>、<code>:n</code> – 退出當前文件並查看下一個文件（使用 <code>↑</code> 鍵、<code>↓</code> 鍵選擇下一個文件）</li></ul><p>要查看 <code>most</code> 的更多詳細信息，可以參考手冊：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man most</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p><code>more</code> – 傳統且基礎的分頁閲讀工具，僅支持向下翻頁和有限次數的向上翻頁。</p><p><code>less</code> – 比 <code>more</code> 功能豐富，支持向下翻頁和向上翻頁，也支持文本搜索。在打開大文件的時候，比 <code>vi</code> 這類文本編輯器啓動得更快。</p><p><code>most</code> – 在上述兩個工具功能的基礎上，還加入了同時打開多個文件、同時鎖定或滾動多個屏幕、分屏等等大量功能。</p><p>以上就是我的介紹，希望能讓你通過我的文章對這三個工具有一定的認識。如果想了解這篇文章以外的關於這幾個工具的詳細功能，請參閲它們的 <code>man</code> 手冊。</p><hr>',80)),d("p",null,[e[1]||(e[1]=s("via: ",-1)),i(o,{href:"https://www.ostechnix.com/the-difference-between-more-less-and-most-commands/"},{default:t(()=>[...e[0]||(e[0]=[s("https://www.ostechnix.com/the-difference-between-more-less-and-most-commands/",-1)])]),_:1})]),d("p",null,[e[6]||(e[6]=s("作者：",-1)),i(o,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...e[2]||(e[2]=[s("SK",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),i(o,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),i(o,{href:"https://github.com/HankChow"},{default:t(()=>[...e[4]||(e[4]=[s("HankChow",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:t(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),d("p",null,[e[12]||(e[12]=s("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),i(o,{href:"https://linux.cn/"},{default:t(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const w=l(r,[["render",h]]);export{C as __pageData,w as default};
